2401	/* Flex container with a bottom border that acts as the tab underline track */
2402	.knowledge-tabs {
2403	  display: flex;
2404	  gap: 0;
2405	  border-bottom: 2px solid var(--color-border);
2406	  margin-bottom: 20px;
2407	}
