2411	.knowledge-tab {
2412	  background: none;
2413	  border: none;
2414	  border-bottom: 2px solid transparent;
2415	  margin-bottom: -2px; /* overlap the track so the active border hides it */
2416	  padding: 8px 16px;
2417	  font-size: 14px;
2418	  font-weight: 500;
2419	  color: var(--color-text-muted);
2420	  cursor: pointer;
2421	  transition: color 0.15s, border-color 0.15s;
2422	  white-space: nowrap;
2423	}
2424	
2425	.knowledge-tab:hover {
2426	  color: var(--color-text);
2427	  border-bottom-color: var(--color-border);
2428	}
2429	
2430	/* Active tab — uses --color-ready for both text and border (AC: tab active state) */
